import test from 'node:test';import assert from 'node:assert/strict';import {accessPreferences,aacChoices,aacEffect,scanStep,gamepadCommands,freshCommands,helperSuggestion,requestHaptic} from '../src/access.js';
test('AAC covers communication and actual activities without pretending future worlds exist',()=>{assert.equal(new Set(aacChoices.map(c=>c.id)).size,aacChoices.length);for(const id of ['explore','solar','mom','dad','bright','loud','save','done'])assert.ok(aacEffect(id));assert.equal(aacEffect('solar').future,true);assert.equal(aacEffect('solar').target,'grounds-elevator');assert.equal(aacEffect('mom').pause,true);assert.equal(aacEffect('done').save,true);assert.equal(aacEffect('bright').dim,true);assert.equal(aacEffect('loud').mute,true);assert.equal(aacEffect('bad'),null)});
test('access preferences validate saved values and scans wrap without timed gameplay demands',()=>{assert.equal(accessPreferences(null).switchMode,'off');assert.equal(accessPreferences({switchMode:'bad',scanMs:-10,haptics:'yes'}).scanMs,3000);assert.equal(accessPreferences({haptics:'yes'}).haptics,false);assert.equal(accessPreferences({switchMode:'two',scanMs:5000}).switchMode,'two');assert.notEqual(accessPreferences({nextKey:'Enter',selectKey:'Enter'}).nextKey,accessPreferences({nextKey:'Enter',selectKey:'Enter'}).selectKey);assert.equal(scanStep(3,4),0);assert.equal(scanStep(0,4,-1),3);assert.equal(scanStep(0,0),0)});
test('standard controller mappings use press edges so held inputs do not repeat',()=>{const buttons=Array.from({length:16},()=>({pressed:false})),pad={connected:true,mapping:'standard',buttons,axes:[0,0]};buttons[0].pressed=true;assert.deepEqual(gamepadCommands(pad),['select']);assert.deepEqual(freshCommands(gamepadCommands(pad),['select']),[]);assert.deepEqual(freshCommands(gamepadCommands(pad),[]),['select']);buttons[0].pressed=false;pad.axes[0]=.9;assert.deepEqual(gamepadCommands(pad),['next']);assert.deepEqual(gamepadCommands({...pad,mapping:''}),[]);assert.deepEqual(gamepadCommands(null),[])});
test('haptics are opt-in and the offline helper suggests an unvisited activity',()=>{let calls=0;const device={vibrate(){calls++;return true}};assert.equal(requestHaptic(false,null,device),false);assert.equal(calls,0);assert.equal(requestHaptic(true,null,device),true);assert.equal(calls,1);assert.equal(requestHaptic(true,null,{}),false);assert.equal(requestHaptic(true,null,{vibrate(){throw Error('unsupported')}}),false);const list=[{id:'gate',kind:'portal'},{id:'rock',kind:'inspect'},{id:'plant',kind:'inspect'}];assert.equal(helperSuggestion(list,new Set(['rock']),null).id,'plant');assert.equal(helperSuggestion([],new Set(),null),null)});
